-- Curated demo creators and illustrative portfolio references for CREOVA marketplace browsing.
CREATE TABLE IF NOT EXISTS hire_requests (
  id BIGSERIAL PRIMARY KEY,
  brand_user_id TEXT NOT NULL,
  creator_user_id TEXT NOT NULL,
  project_title TEXT NOT NULL,
  work_description TEXT NOT NULL,
  content_type TEXT NOT NULL DEFAULT 'AI filmmaking',
  proposed_budget NUMERIC(12,2) NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'INR',
  requested_date DATE,
  requested_time TEXT NOT NULL DEFAULT '',
  timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata',
  duration TEXT NOT NULL DEFAULT '',
  deliverables JSONB NOT NULL DEFAULT '[]'::jsonb,
  formats JSONB NOT NULL DEFAULT '[]'::jsonb,
  commercial_use BOOLEAN NOT NULL DEFAULT false,
  licensing_requirements TEXT NOT NULL DEFAULT '',
  extra_notes TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','declined','cancelled')),
  email_status TEXT NOT NULL DEFAULT 'not_attempted',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  responded_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS hire_requests_brand_idx ON hire_requests(brand_user_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS hire_requests_creator_idx ON hire_requests(creator_user_id, status, created_at DESC);

-- Narrow insert policies allow only the fixed demo-ID namespace used by this seed.
DROP POLICY IF EXISTS creova_demo_profiles_seed_insert ON app_profiles;
CREATE POLICY creova_demo_profiles_seed_insert ON app_profiles FOR INSERT WITH CHECK (user_id LIKE 'demo_creator_creova_%');
DROP POLICY IF EXISTS creova_demo_portfolio_seed_insert ON portfolio_items;
CREATE POLICY creova_demo_portfolio_seed_insert ON portfolio_items FOR INSERT WITH CHECK (creator_user_id LIKE 'demo_creator_creova_%');

